mkdir -p ~/deploy/tools; cat > ~/deploy/tools/httpget.pl <<'EOF'
#!/usr/bin/perl
# Minimal HTTP GET bound to a given source IP (the UE's uesimtun0 address), so the
# request is routed through the 5G user plane via UERANSIM's "from <ue-ip> lookup rt_uesimtun0" rule.
use strict; use IO::Socket::INET;
my ($src, $host, $port, $path) = @ARGV; $port ||= 80; $path ||= "/";
my $s = IO::Socket::INET->new(PeerAddr=>$host, PeerPort=>$port, LocalAddr=>$src, Proto=>'tcp', Timeout=>5)
  or die "connect failed: $!\n";
print $s "GET $path HTTP/1.0\r\nHost: $host\r\nConnection: close\r\n\r\n";
print while <$s>;
EOF
UE=$(kubectl get pod -n free5gc -l app=ueransim,component=ue -o name); kubectl cp ~/deploy/tools/httpget.pl free5gc/${UE#pod/}:/tmp/httpget.pl; kubectl exec -n free5gc $UE -- perl /tmp/httpget.pl 10.60.128.1 10.43.200.10 80 /

